func TestEnumOptOutSource(t *testing.T) {
	t.Run("NewFromString_inbound", func(t *testing.T) {
		t.Parallel()
		val, err := NewOptOutSourceFromString("inbound")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, OptOutSource("inbound"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_manual", func(t *testing.T) {
		t.Parallel()
		val, err := NewOptOutSourceFromString("manual")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, OptOutSource("manual"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewOptOutSourceFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewOptOutSourceFromString("inbound")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

